// Generate a unique Event ID
const eventId = 'EVT-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).substring(2, 6).toUpperCase();
const eventName = $input.first().json.body?.event_name || 'Event';
const formBaseUrl = $input.first().json.body?.form_url || '';

// Build the pre-filled Google Form URL
// The entry ID for the hidden Event_ID field in your Google Form
const formUrl = formBaseUrl 
  ? `${formBaseUrl}?entry.EVENT_ID_FIELD=${encodeURIComponent(eventId)}`
  : `https://docs.google.com/forms/d/e/YOUR_FORM_ID/viewform?entry.EVENT_ID_FIELD=${encodeURIComponent(eventId)}`;

// QuickChart QR code URL (free, no API key)
const qrUrl = `https://quickchart.io/qr?text=${encodeURIComponent(formUrl)}&size=400&dark=6a0dad&format=png`;

return [
  {
    json: {
      event_id: eventId,
      event_name: eventName,
      form_url: formUrl,
      qr_url: qrUrl,
      created_at: new Date().toISOString()
    }
  }
];

