const response = $input.first().json;
let sentiment = 'needs growth'; // default

try {
  const content = response.choices[0].message.content.trim().toLowerCase();
  if (content.includes('empath')) {
    sentiment = 'empath';
  } else {
    sentiment = 'needs growth';
  }
} catch (e) {
  sentiment = 'needs growth';
}

return [
  {
    json: {
      sentiment: sentiment,
      anonymous_id: $('PII Scrubber (Privacy Shield)').item.json.anonymous_id,
      feedback_sanitized: $('PII Scrubber (Privacy Shield)').item.json.feedback_sanitized,
      row_number: $('PII Scrubber (Privacy Shield)').item.json.row_number
    }
  }
];
